ps":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"integer","label":"Integer"},{"id":"floating-point","label":"Floating point"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"}],"feedback":{"correct":"Name is text, quantity is a whole number, price may include pence, and delivery is yes/no.","incorrect":"Ask: is it text, a whole number, a number that may include a fraction, or true/false?"},"formative":true,"items":[{"correctCategoryId":"string","id":"customer-name","label":"Customer name"},{"correctCategoryId":"integer","id":"item-quantity","label":"Number of items"},{"correctCategoryId":"floating-point","id":"unit-price","label":"Unit price"},{"correctCategoryId":"boolean","id":"delivery-flag","label":"Delivery required"}],"prompt":"Choose the most appropriate fundamental data type for each item.","questionId":"u14-w1-biz-class"},"id":"w1-biz-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"guidance":"A price can include a fractional amount, such as 12.50. An integer can only store whole numbers.","prompt":"Why is a floating point type more appropriate than an integer for a product price?","questionId":"u14-w1-biz-why"},"id":"w1-biz-why","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"prompt":"Name one workplace system you have seen (till, booking, stock). What data does it store?","questionId":"u14-w1-biz-ref"},"id":"w1-biz-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"text":"Expected types are included in this activity JSON for instant feedback. This is not Assignment 1 marking.","title":"Formative classification","tone":"info"},"id":"w1-biz-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-1-business-data-explorer","metadata":{"href":null,"status":"available","summary":"Connect software in a workplace to the data it stores, then classify business values using integer, floating point, string and Boolean.","title":"Business data explorer"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"Unit 14 is internally assessed. Week 1 starts Assignment 1 (P1): explain universal programming constructs with worked examples. Completing this activity is practice, not P1 achieved."},"id":"w1-var-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"A variable is a named store for a value. The type describes what kind of value it holds."},"id":"w1-var-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"label":"Read these Python examples, then add one more variable of your own.","language":"python","questionId":"u14-w1-var-code","starter":"customer_name = \"Patel\"\nquantity = 3\nunit_price = 12.5\ndelivery_required = True\n"},"id":"w1-var-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"correctOptionId":"boolean","feedback":{"correct":"Paid or not paid is a Boolean.","incorrect":"A yes/no business fact is stored as Boolean."},"formative":true,"options":[{"id":"integer","label":"Integer"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"},{"id":"floating-point","label":"Floating point"}],"prompt":"Which fundamental type should store whether an invoice has been paid?","questionId":"u14-w1-var-q1"},"id":"w1-var-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"guidance":"A value is the data itself (for example 3). A variable is the named store that holds that value.","prompt":"In your own words, what is the difference between a variable and a value?","questionId":"u14-w1-var-why"},"id":"w1-var-short","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-1-variables-and-data-types","metadata":{"href":null,"status":"available","summary":"Learn what a variable is and when to use integer, floating point, string and Boolean in a business program.","title":"Variables and fundamental data types"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"print() shows information to the user. input() reads text the user types and you store it in a variable. Use the agreed Python environment for this unit."},"id":"w1-io-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include input(), store the result in a variable, and use print().","passFeedback":"The program uses input, a variable and print. This is formative structure checking, not code execution.","required":[{"label":"input()","pattern":"input\\s*\\("},{"label":"print()","pattern":"print\\s*\\("},{"label":"assignment","pattern":"="}]},"hints":["Call input() to capture the name.","Use print() to show the confirmation."],"instructions":"Complete the program so it asks for a product name and prints a confirmation. Do not run untrusted code in the browser; the check looks for input() and print() only.","label":"Python editor","language":"python","questionId":"u14-w1-io-code","starter":"product_name = input(\"Product name: \")\n# Print a confirmation that includes the product name.\n"},"id":"w1-io-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"input() returns text. Week 2 looks at converting types in more depth.","incorrect":"input() returns text. Whole numbers need a later conversion step."},"formative":true,"options":[{"id":"a","label":"Always an integer"},{"id":"b","label":"Text (a string)"},{"id":"c","label":"True or False"}],"prompt":"What does input() return in Python?","questionId":"u14-w1-io-q1"},"id":"w1-io-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-1-input-and-output","metadata":{"href":null,"status":"available","summary":"Use print to display information and input to capture business data into variables.","title":"Print and input"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"GitHub Classroom provisions your repository. Accept the invitation from your teacher, open the repository, and clone it locally. Use the agreed Python environment to edit files in that clone."},"id":"w1-gh-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Inspect the README and any template files before you type new code. The hub cannot accept GitHub sign-in and does not clone for you."},"id":"w1-gh-p2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"1. Accept the Classroom invitation.\n2. Open the provisioned repository on GitHub.\n3. Clone it to your computer.\n4. Open the project in your Python environment."},"id":"w1-gh-steps","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"GitHub remains the authentic development environment.","incorrect":"The hub guides you. GitHub holds the repository."},"formative":true,"options":[{"id":"a","label":"Only inside this hub"},{"id":"b","label":"In the GitHub repository provisioned by Classroom"},{"id":"c","label":"In an email attachment"}],"prompt":"Where should your Unit 14 code repository live?","questionId":"u14-w1-gh-q1"},"id":"w1-gh-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"prompt":"Write the clone command or steps you will use, or note if you still need teacher help to clone.","questionId":"u14-w1-gh-ref"},"id":"w1-gh-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-1-github-classroom-guidance","metadata":{"href":null,"status":"available","summary":"Accept the Classroom assignment and use GitHub as the real repository. This hub does not replace GitHub.","title":"GitHub Classroom and the Python environment"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"correctOptionId":"string","feedback":{"correct":"An email address is text.","incorrect":"Text values use the string type."},"formative":true,"options":[{"id":"integer","label":"Integer"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"}],"prompt":"Which type best stores a customer email address?","questionId":"u14-w1-rev-q1"},"id":"w1-rev-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"print() displays output.","incorrect":"print() displays output. input() reads from the user."},"formative":true,"options":[{"id":"a","label":"input()"},{"id":"b","label":"print()"},{"id":"c","label":"clone()"}],"prompt":"Which statement displays output in Python?","questionId":"u14-w1-rev-q2"},"id":"w1-rev-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"categories":[{"id":"integer","label":"Integer"},{"id":"floating-point","label":"Floating point"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"}],"feedback":{"correct":"Stock is a whole number; paid is true/false.","incorrect":"Use integer for counts and Boolean for yes/no facts."},"formative":true,"items":[{"correctCategoryId":"integer","id":"stock-count","label":"Items in stock"},{"correctCategoryId":"boolean","id":"paid","label":"Invoice paid"}],"prompt":"Classify these Week 1 business values.","questionId":"u14-w1-rev-class"},"id":"w1-rev-q3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-1-review","metadata":{"href":null,"status":"available","summary":"A short recap of variables, the four fundamental types, print and input. No Week 2 conversion content.","title":"Week 1 retrieval"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"A cafe records takeaway orders. For each data item, choose a fundamental type."},"id":"w1-g-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"categories":[{"id":"integer","label":"Integer"},{"id":"floating-point","label":"Floating point"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"}],"feedback":{"correct":"Names and notes are strings, cup count is an integer, price is floating point, loyalty is Boolean.","incorrect":"Match each value to text, whole number, fractional number, or true/false."},"formative":true,"items":[{"correctCategoryId":"string","id":"drink-name","label":"Drink name"},{"correctCategoryId":"integer","id":"cup-count","label":"Number of cups"},{"correctCategoryId":"floating-point","id":"price","label":"Price of the drink"},{"correctCategoryId":"boolean","id":"loyalty","label":"Customer is on the loyalty scheme"},{"correctCategoryId":"string","id":"notes","label":"Special request notes"}],"prompt":"Classify the cafe order data.","questionId":"u14-w1-guided-class"},"id":"w1-g-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"guidance":"You cannot sell 2.7 cups in this scenario. A count of cups is a whole number, so integer is appropriate.","prompt":"Explain why number of cups is an integer rather than a floating point value.","questionId":"u14-w1-guided-why"},"id":"w1-g-why","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-1-guided-business-data","metadata":{"href":null,"status":"available","summary":"Select an appropriate type for several items in a small business scenario and explain at least one choice.","title":"Guided business-data practice"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"After you clone the repository, commit small, meaningful changes and push them to GitHub."},"id":"w1-c-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"attribution":"Example of a good commit message","text":"Add customer name and order quantity input"},"id":"w1-c-good","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"quote","version":"0.1.0"},{"content":{"attribution":"Example of a poor commit message","text":"update"},"id":"w1-c-bad","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"quote","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"The message says what changed and why it matters to the order program.","incorrect":"Prefer a message that names the business data you added."},"formative":true,"options":[{"id":"a","label":"update"},{"id":"b","label":"Add customer name and order quantity input"},{"id":"c","label":"asdf"}],"prompt":"Which commit message better describes Week 1 work?","questionId":"u14-w1-commit-q1"},"id":"w1-c-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"prompt":"Write the commit message you will use for your first Week 1 change.","questionId":"u14-w1-commit-ref"},"id":"w1-c-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-1-first-commits","metadata":{"href":null,"status":"available","summary":"Make meaningful incremental commits in the Classroom repository. The hub does not run Git for you.","title":"Clone, commits and push"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"Ask for business-order information, store each piece in a variable with an appropriate type, and print a summary. Do not add Week 2 conversion work beyond the int() scaffold for quantity."},"id":"w1-py-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include input(), print(), and variables for the order data.","passFeedback":"The structure uses input, variables and print. Run the file in your Python environment and commit it on GitHub.","required":[{"label":"input()","pattern":"input\\s*\\("},{"label":"print()","pattern":"print\\s*\\("},{"label":"business variables","pattern":"customer_name|quantity|unit_price|delivery"}]},"hints":["Use input() for each prompt.","Print a labelled summary of all four values.","Commit this file in your GitHub repository, not only in the hub."],"instructions":"Keep the four fundamental types in mind: name as string, quantity as integer, price as a number that may include pence, delivery as a yes/no fact. The browser does not execute this program.","label":"Python editor","language":"python","questionId":"u14-w1-order-code","starter":"# Business order \u2014 Week 1\n# input() returns text. int() is used only so quantity is a whole number.\n\ncustomer_name = input(\"Customer name: \")\nquantity = int(input(\"Number of items: \"))\nunit_price = input(\"Unit price: \")\ndelivery_required = input(\"Delivery required (True/False): \")\n\nprint(\"Order summary\")\nprint(\"Customer:\", customer_name)\nprint(\"Quantity:\", quantity)\nprint(\"Unit price:\", unit_price)\nprint(\"Delivery required:\", delivery_required)\n"},"id":"w1-py-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"prompt":"Which variable was hardest to type, and why?","questionId":"u14-w1-order-ref"},"id":"w1-py-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-1-first-python-business-program","metadata":{"href":null,"status":"available","summary":"Create a simple program that asks for business-order information, stores it in variables and prints a formatted summary.","title":"First Python business-order program"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"P1 asks you to show understanding of the programming constructs used to build software for business. Hub completion is not P1 achieved. Submit the technical guide through the approved assignment process."},"id":"w1-a1-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Record:\n\n* what a variable is\n* integer, floating point, string and Boolean, each with a business use\n* a short worked Python example\n* the purpose of the example, not only the syntax"},"id":"w1-a1-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"},{"content":{"prompt":"Draft one paragraph for your guide: define a variable and give a business example.","questionId":"u14-w1-a1-notes"},"id":"w1-a1-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"href":"assignments/assignment-1/","label":"Open the Assignment 1 workspace"},"id":"w1-a1-link","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reference","version":"0.1.0"},{"content":{"text":"The hub never awards Pass, Merit or Distinction. Your teacher assesses the submitted guide.","title":"Not a grade","tone":"warning"},"id":"w1-a1-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-1-assignment-1-guide","metadata":{"href":null,"status":"available","summary":"Start P1 evidence: define a variable, explain each fundamental type, include a worked Python example and its business purpose.","title":"Assignment 1 technical-guide starter"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"text":"Independent study: extend the program, use at least six pieces of business data, cover integer, floating point, string and Boolean, commit and push, then extend your Assignment 1 notes."},"id":"w1-hw-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Keep input(), print() and several variable assignments.","passFeedback":"The extension still uses input, variables and print. Commit and push on GitHub, then add the example to your technical guide.","required":[{"label":"input()","pattern":"input\\s*\\("},{"label":"print()","pattern":"print\\s*\\("},{"label":"assignment","pattern":"="}]},"hints":["Include at least six variables.","Keep all four fundamental types in the data you collect."],"instructions":"Work in your cloned repository. The check only looks for input, print and several assignments. It does not execute code or award P1.","label":"Python editor","language":"python","questionId":"u14-w1-hw-code","starter":"# Homework extension \u2014 at least six pieces of business data\n# Cover string, integer, floating point and Boolean.\n\ncustomer_name = input(\"Customer name: \")\nproduct_name = input(\"Product name: \")\nquantity = int(input(\"Quantity: \"))\nunit_price = input(\"Unit price: \")\ndelivery_required = input(\"Delivery required (True/False): \")\nloyalty_member = input(\"Loyalty member (True/False): \")\n\nprint(\"Extended order summary\")\nprint(customer_name, product_name, quantity, unit_price, delivery_required, loyalty_member)\n"},"id":"w1-hw-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"prompt":"List the six (or more) data items and the type you chose for each.","questionId":"u14-w1-hw-ref"},"id":"w1-hw-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"text":"After this homework, Week 2 will cover data type conversion and predefined subroutines. Do not start conversion work yet. Continue the Assignment 1 technical guide with this week's variables and types only.","title":"What next","tone":"info"},"id":"w1-hw-next","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"href":"assignments/assignment-1/","label":"Continue Assignment 1 notes"},"id":"w1-hw-link","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reference","version":"0.1.0"}],"id":"week-1-homework-extension","metadata":{"href":null,"status":"available","summary":"Extend the order program with at least six pieces of business data covering all four fundamental types, then commit, push and add to the Assignment 1 guide.","title":"Homework: extend the business-order program"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Four fundamental types"},"id":"w2-ret-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Week 1 used integer, floating point, string and Boolean to store business data. This check is formative only. It is not a grade and is not P1."},"id":"w2-ret-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"12.50 is a floating-point number. Quotes would make it a string.","incorrect":"A floating-point number includes a fractional part and is not wrapped in quotes."},"formative":true,"options":[{"id":"a","label":"17"},{"id":"b","label":"12.50"},{"id":"c","label":"\"12.50\""},{"id":"d","label":"True"}],"prompt":"Which value is a floating-point number?","questionId":"u14-w2-ret-q1"},"id":"w2-ret-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"c","feedback":{"correct":"Names are text, including accents, hyphens and more than one word.","incorrect":"A name is text. Do not force it into a number or a true/false value."},"formative":true,"options":[{"id":"a","label":"Integer"},{"id":"b","label":"Boolean"},{"id":"c","label":"String"}],"prompt":"Customer name \"Ng\u1ecdc Tr\u1ea7n-Garc\u00eda\" should be stored as which type?","questionId":"u14-w2-ret-q2"},"id":"w2-ret-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"categories":[{"id":"integer","label":"Integer"},{"id":"floating-point","label":"Floating point"},{"id":"string","label":"String"},{"id":"boolean","label":"Boolean"}],"feedback":{"correct":"Those four types are the Week 1 foundation for this week's conversion work.","incorrect":"Quantity is a whole number, price may include pence, names are text, and delivery is yes/no."},"formative":true,"items":[{"correctCategoryId":"integer","id":"qty","label":"Number of items ordered"},{"correctCategoryId":"floating-point","id":"price","label":"Unit price in pounds and pence"},{"correctCategoryId":"string","id":"name","label":"Customer name"},{"correctCategoryId":"boolean","id":"delivery","label":"Delivery required"}],"prompt":"Match each Week 1 business value to its fundamental type.","questionId":"u14-w2-ret-class"},"id":"w2-ret-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"text":"Correct options are stored in the hub for instant feedback. They are not secure assignment evidence.","title":"Formative only","tone":"info"},"id":"w2-ret-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-2-week-1-retrieval","metadata":{"href":null,"status":"available","summary":"A short formative check of the four fundamental data types before conversion teaching.","title":"Week 1 retrieval"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"input() returns text"},"id":"w2-prob-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Python input() always returns a string. If a cashier types 10, the program stores \"10\", not the integer 10. Arithmetic needs a numeric type first."},"id":"w2-prob-p1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"instructions":"This fragment shows the conversion problem. The browser does not run it. Predict the output, then answer below.","label":"Read this example","language":"python","questionId":"u14-w2-prob-demo","starter":"first = input(\"First quantity: \")   # learner types 10\nsecond = input(\"Second quantity: \") # learner types 5\nprint(first + second)\n"},"id":"w2-prob-code","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"The + operator concatenates strings, so \"10\" + \"5\" is \"105\".","incorrect":"Both values are strings. + joins them as text rather than adding them as numbers."},"formative":true,"options":[{"id":"a","label":"15"},{"id":"b","label":"105"},{"id":"c","label":"10 5"}],"prompt":"If the user types 10 and then 5, what does print(first + second) display?","questionId":"u14-w2-prob-q1"},"id":"w2-prob-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Conversion is needed because input() returns text.","incorrect":"print() can display numbers. The issue is that input() returns a string."},"formative":true,"options":[{"id":"a","label":"Because input() returns a string"},{"id":"b","label":"Because print() cannot display numbers"},{"id":"c","label":"Because GitHub rejects integers"}],"prompt":"Why must quantity be converted before it is used in arithmetic?","questionId":"u14-w2-prob-q2"},"id":"w2-prob-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"guidance":"A typical answer mentions that typed input is text, and text cannot be multiplied or added as money or stock.","prompt":"In one or two sentences, explain why a business program must convert quantity before calculating a total.","questionId":"u14-w2-prob-why"},"id":"w2-prob-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"text":"Users type unexpected values. Treating all input as trusted numbers is a common source of defects. Convert deliberately, and expect invalid text.","title":"Unreliable input","tone":"warning"},"id":"w2-prob-ind","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-2-conversion-problem","metadata":{"href":null,"status":"available","summary":"Show that input() returns a string and that \"10\" + \"5\" concatenates instead of adding.","title":"Why conversion is necessary"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"int, float, str and bool"},"id":"w2-conv-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Convert with int(), float(), str() and bool() before you calculate or store a typed value. Convert as close as possible to the input, then use the typed variable."},"id":"w2-conv-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"instructions":"Read these conversions. int(\"10\") is 10. float(\"12.50\") is 12.5. str(10) is \"10\". bool(0) is False; any non-zero number is True.","label":"Worked conversion examples","language":"python","questionId":"u14-w2-conv-examples","starter":"quantity = int(input(\"Quantity: \"))\nprice = float(input(\"Unit price: \"))\nlabel = str(quantity)\nflag = bool(quantity)\n"},"id":"w2-conv-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Prices include pence, so float() is the matching conversion.","incorrect":"int(\"12.50\") raises ValueError. bool() would only test whether text was typed."},"formative":true,"options":[{"id":"a","label":"int(input(\"Price: \"))"},{"id":"b","label":"float(input(\"Price: \"))"},{"id":"c","label":"bool(input(\"Price: \"))"}],"prompt":"Which call is appropriate for a price typed as 12.50?","questionId":"u14-w2-conv-q1"},"id":"w2-conv-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"instructions":"This program is meant to fail. Do not \"fix\" it here. Read the error you would see in Python, then interpret it below.","label":"Deliberate failure","language":"python","questionId":"u14-w2-conv-fail","starter":"quantity = int(input(\"Quantity: \"))\n# If the user types ten, Python raises:\n# ValueError: invalid literal for int() with base 10: 'ten'\n"},"id":"w2-conv-fail","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"guidance":"int() cannot convert the letters ten. Python raises ValueError. The program stops unless later weeks add handling.","prompt":"A user types ten instead of 10. What happens, and what does the error tell you?","questionId":"u14-w2-conv-err"},"id":"w2-conv-err","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"text":"bool(\"False\") is True because the string is not empty. Do not use bool() to interpret the words True and False typed by a user.","title":"bool() on text","tone":"info"},"id":"w2-conv-bool","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include int() for quantity and float() for price.","passFeedback":"int() and float() are present. Run the file in your Python environment to see conversion work or fail.","required":[{"label":"int()","pattern":"int\\s*\\("},{"label":"float()","pattern":"float\\s*\\("}]},"hints":["Use int() for quantity.","Use float() for price.","Multiply only after conversion."],"instructions":"Convert quantity with int() and price with float() before any arithmetic. The check looks for those calls only. The browser does not execute the program.","label":"Python editor","language":"python","questionId":"u14-w2-conv-code","starter":"quantity_text = input(\"Quantity: \")\nprice_text = input(\"Unit price: \")\n# Convert, then calculate a line total.\n"},"id":"w2-conv-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"}],"id":"week-2-conversion-demonstration","metadata":{"href":null,"status":"available","summary":"Teach int(), float(), str() and bool(), including a deliberate conversion failure.","title":"Conversion functions"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Cleaning business text"},"id":"w2-sub-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Customer records arrive messy: extra spaces, mixed case, commas in addresses. Predefined subroutines clean that text. Choose the operation that matches the job."},"id":"w2-sub-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"instructions":"Read these examples. Keep legitimate names such as Mary-Anne, O'Neill and Ng\u1ecdc. Do not strip hyphens or apostrophes just to make data simpler.","label":"Worked string operations","language":"python","questionId":"u14-w2-sub-examples","starter":"raw_name = \"  jane smith  \"\nname = raw_name.strip().title()\nemail = \"Jane.Smith@Example.com\".lower()\nparts = \"12 High Street, Leeds\".split(\",\")\npostcode = \"ls1 4ap\".upper()\nlength = len(name)\nclean = \"Order  #12\".replace(\"  \", \" \")\n"},"id":"w2-sub-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"categories":[{"id":"len","label":"len"},{"id":"upper","label":"upper"},{"id":"lower","label":"lower"},{"id":"strip","label":"strip"},{"id":"split","label":"split"},{"id":"replace","label":"replace"}],"feedback":{"correct":"Each subroutine has a specific job. Matching the job to the call is the Week 2 skill.","incorrect":"strip spaces, lower emails, upper postcodes, split on a separator, replace a substring, len for length."},"formative":true,"items":[{"correctCategoryId":"strip","id":"spaces","label":"Remove leading and trailing spaces from a name"},{"correctCategoryId":"lower","id":"email","label":"Store an email address in a consistent case"},{"correctCategoryId":"upper","id":"postcode","label":"Display a UK postcode in capitals"},{"correctCategoryId":"split","id":"address","label":"Separate \"12 High Street, Leeds\" into street and city"},{"correctCategoryId":"replace","id":"typo","label":"Change \"Stret\" to \"Street\" in an address"},{"correctCategoryId":"len","id":"count","label":"Check that a product code is 8 characters long"}],"prompt":"Choose the most appropriate subroutine for each job.","questionId":"u14-w2-sub-class"},"id":"w2-sub-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include strip() and lower().","passFeedback":"strip() and lower() are present. Preserve legitimate name punctuation when you run this in Python.","required":[{"label":"strip()","pattern":"strip\\s*\\("},{"label":"lower()","pattern":"lower\\s*\\("}]},"hints":["strip() removes surrounding spaces.","lower() makes email comparison consistent.","Keep the hyphen and apostrophe in the name."],"instructions":"Clean the customer name with strip and make the email lower case. The check looks for those calls. It does not execute code.","label":"Python editor","language":"python","questionId":"u14-w2-sub-code","starter":"raw_name = \"  Mary-Anne O'Neill  \"\nraw_email = \"Mary.Anne@Example.com\"\n# Clean the name and email for a business record.\n"},"id":"w2-sub-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"}],"id":"week-2-predefined-subroutines","metadata":{"href":null,"status":"available","summary":"Select len, upper, lower, strip, split and replace for realistic business data.","title":"Predefined string subroutines"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"f-strings for business output"},"id":"w2-fmt-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"A receipt should be readable: labels, currency and two decimal places. f-strings place converted values into that layout."},"id":"w2-fmt-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"instructions":"Read this receipt layout. Labels, currency and two decimal places sit in f-strings.","label":"Worked receipt","language":"python","questionId":"u14-w2-fmt-example","starter":"customer = \"River Caf\u00e9\"\nsubtotal = 18.5\nvat = subtotal * 0.2\ntotal = subtotal + vat\nprint(f\"Customer: {customer}\")\nprint(f\"Subtotal: \u00a3{subtotal:.2f}\")\nprint(f\"VAT (20%): \u00a3{vat:.2f}\")\nprint(f\"Total: \u00a3{total:.2f}\")\n"},"id":"w2-fmt-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Print with an f-string and include subtotal, VAT or total.","passFeedback":"The receipt uses an f-string and business totals. Run it in Python to confirm the layout.","required":[{"label":"f-string print","pattern":"print\\s*\\(\\s*f[\"']"},{"label":"business totals","pattern":"subtotal|vat|total"}]},"hints":["Calculate vat as subtotal * vat_rate.","Use print(f\"...\") for labelled lines.",":.2f keeps pence on money values."],"instructions":"Complete the receipt using an f-string. Include subtotal, VAT and total. The browser does not execute this.","label":"Python editor","language":"python","questionId":"u14-w2-fmt-code","starter":"customer = \"River Caf\u00e9\"\nsubtotal = 18.5\nvat_rate = 0.2\n# Calculate VAT and total, then print a labelled receipt with f-strings.\n"},"id":"w2-fmt-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"f-strings format values in place. They do not replace conversion.","incorrect":"You still convert numbers first. f-strings only control how the output is written."},"formative":true,"options":[{"id":"a","label":"It keeps labels and converted values in one readable line"},{"id":"b","label":"It converts strings to integers automatically"},{"id":"c","label":"It uploads the receipt to GitHub"}],"prompt":"Why use an f-string on a receipt instead of joining several strings with + ?","questionId":"u14-w2-fmt-q1"},"id":"w2-fmt-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"}],"id":"week-2-formatted-output","metadata":{"href":null,"status":"available","summary":"Use f-strings to produce a professional receipt-style summary.","title":"Formatted business output"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Keep generated files out of Git"},"id":"w2-gi-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"The Classroom repository includes a .gitignore. Git uses it to skip files that should not be committed: Python cache, virtual environments and editor settings."},"id":"w2-gi-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Typical supplied entries include Python cache (__pycache__/, *.pyc), virtual environments (.venv/) and editor folders (.idea/, .vscode/). These are generated or local. They are not the business program. Committing them clutters history and can leak editor or machine-specific files."},"id":"w2-gi-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"Cache is rebuilt locally. Source and .gitignore belong in Git; cache does not.","incorrect":"Ignoring cache does not stop Python. It keeps the repository about the program."},"formative":true,"options":[{"id":"a","label":"It is generated cache, not source the team should review"},{"id":"b","label":"Python cannot run if the folder is ignored"},{"id":"c","label":"GitHub deletes ignored folders from the classroom"}],"prompt":"Why should __pycache__/ stay out of the repository?","questionId":"u14-w2-gi-q1"},"id":"w2-gi-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"instructions":"This is not Python to run. Add one extra ignored entry such as .DS_Store or *.log under the comment.","label":".gitignore excerpt","language":"python","questionId":"u14-w2-gi-add","starter":"__pycache__/\n*.pyc\n.venv/\n.idea/\n.vscode/\n# Add one extra generated or local pattern below.\n"},"id":"w2-gi-code","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"guidance":"A generated or machine-specific file (for example .DS_Store or a log) does not help another learner run the business program.","prompt":"Which extra pattern did you add, and why should that file stay local?","questionId":"u14-w2-gi-why"},"id":"w2-gi-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"text":"A professional repository contains source, tests and agreed config. After changing .gitignore, remove any already-tracked cache from the index in Git itself. This hub does not run Git.","title":"Clean repository","tone":"info"},"id":"w2-gi-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-2-gitignore","metadata":{"href":null,"status":"available","summary":"Explain the supplied .gitignore, ignored generated files, and how to add an extra ignore rule.","title":"Reading and extending .gitignore"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Before the lab"},"id":"w2-rev-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Recap only: convert before arithmetic, and pick the subroutine that matches the data job."},"id":"w2-rev-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"b","feedback":{"correct":"Without int(), + concatenates the two strings.","incorrect":"input() returns strings. Convert before you add as numbers."},"formative":true,"options":[{"id":"a","label":"5"},{"id":"b","label":"\"32\""},{"id":"c","label":"6"}],"prompt":"A user types 3 and 2. quantity = input(...) then extra = input(...). What is quantity + extra?","questionId":"u14-w2-rev-q1"},"id":"w2-rev-q1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"c","feedback":{"correct":"strip() removes leading and trailing spaces.","incorrect":"split() breaks on a separator. replace() swaps a substring. strip() trims edges."},"formative":true,"options":[{"id":"a","label":"split()"},{"id":"b","label":"replace()"},{"id":"c","label":"strip()"}],"prompt":"Which call removes spaces from both ends of \"  Leeds  \"?","questionId":"u14-w2-rev-q2"},"id":"w2-rev-q2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"categories":[{"id":"int","label":"int()"},{"id":"float","label":"float()"},{"id":"strip","label":"strip()"},{"id":"split","label":"split()"}],"feedback":{"correct":"Match the job: whole number, money, trim, or split.","incorrect":"int for whole numbers, float for money, strip for edges, split for separators."},"formative":true,"items":[{"correctCategoryId":"int","id":"qty","label":"Turn typed quantity \"4\" into a whole number"},{"correctCategoryId":"float","id":"price","label":"Turn typed price \"9.99\" into a number with pence"},{"correctCategoryId":"strip","id":"name","label":"Remove spare spaces around a surname"},{"correctCategoryId":"split","id":"csv","label":"Break \"name,email\" into two fields"}],"prompt":"Choose conversion or subroutine for each task.","questionId":"u14-w2-rev-class"},"id":"w2-rev-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"}],"id":"week-2-review","metadata":{"href":null,"status":"available","summary":"Short recap of conversion and choosing an appropriate predefined subroutine.","title":"Session 2 retrieval"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Repair missing conversion"},"id":"w2-dbg-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Each program is deliberately broken. Inspect the problem, repair it in the editor, then explain the cause. Checks look for conversion calls. They do not execute Python in the browser."},"id":"w2-dbg-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Convert both quantities with int() before adding.","passFeedback":"int() is present. In Python, 10 and 5 should now total 15, not 105.","required":[{"label":"int()","pattern":"int\\s*\\("}]},"hints":["input() returns a string.","int() each value before +."],"instructions":"Program 1: two quantities are added as text. Convert both with int() before adding.","label":"Python editor","language":"python","questionId":"u14-w2-dbg-1","starter":"first = input(\"First quantity: \")\nsecond = input(\"Second quantity: \")\nprint(\"Total items:\", first + second)\n"},"id":"w2-dbg-1","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"guidance":"+ concatenated two strings. The values needed int() before numeric addition.","prompt":"Program 1: what went wrong before the repair?","questionId":"u14-w2-dbg-1e"},"id":"w2-dbg-1e","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Convert the price with float() before multiplying.","passFeedback":"float() is present. Run it in Python to confirm VAT is calculated.","required":[{"label":"float()","pattern":"float\\s*\\("}]},"hints":["A string cannot be multiplied by 1.2.","float() converts money text."],"instructions":"Program 2: a price is multiplied by 1.2 without conversion. Use float().","label":"Python editor","language":"python","questionId":"u14-w2-dbg-2","starter":"price = input(\"Unit price: \")\nprint(\"Price including VAT:\", price * 1.2)\n"},"id":"w2-dbg-2","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"guidance":"price was still a string. Python cannot multiply that string by 1.2. float() is required.","prompt":"Program 2: why did price * 1.2 fail?","questionId":"u14-w2-dbg-2e"},"id":"w2-dbg-2e","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Replace int() with float() for a price that includes pence.","passFeedback":"float() is present. int() is the wrong tool for 12.50.","required":[{"label":"float()","pattern":"float\\s*\\("}]},"hints":["int(\"12.50\") raises ValueError.","Money with pence needs float()."],"instructions":"Program 3: int() is the wrong conversion for a price with pence. Use float().","label":"Python editor","language":"python","questionId":"u14-w2-dbg-3","starter":"price = int(input(\"Unit price: \"))  # user types 12.50\nprint(\"Price:\", price)\n"},"id":"w2-dbg-3","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"guidance":"ValueError: invalid literal for int(). float(\"12.50\") is the matching conversion.","prompt":"Program 3: what error does int(\"12.50\") cause, and which conversion is correct?","questionId":"u14-w2-dbg-3e"},"id":"w2-dbg-3e","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Convert age with int() before comparing with 18.","passFeedback":"int() is present. The comparison can now use a whole number.","required":[{"label":"int()","pattern":"int\\s*\\("}]},"hints":["Python 3 cannot compare a string with an integer using >.","Convert age with int() first."],"instructions":"Program 4: a typed age is compared with 18 without conversion. Use int().","label":"Python editor","language":"python","questionId":"u14-w2-dbg-4","starter":"age = input(\"Age: \")\nprint(\"Adult ticket:\", age > 18)\n"},"id":"w2-dbg-4","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"guidance":"input() is a string. Comparing it with 18 is a type error. Convert with int() first.","prompt":"Program 4: why must age be converted before age > 18?","questionId":"u14-w2-dbg-4e"},"id":"w2-dbg-4e","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Do not rely on bool() for the words True and False. Compare the text.","passFeedback":"The program compares the typed words instead of using bool() on text.","prohibited":[{"label":"bool() on text","pattern":"bool\\s*\\("}],"required":[{"flags":"i","label":"text comparison","pattern":"\\.lower\\s*\\(|==\\s*[\"']true[\"']"}]},"hints":["bool(\"False\") is True because the string is not empty.","Compare normalised text, such as member.lower() == \"true\"."],"instructions":"Program 5: bool() is the wrong conversion for the words True/False. Compare the text instead (for example member.lower() == \"true\").","label":"Python editor","language":"python","questionId":"u14-w2-dbg-5","starter":"member = input(\"Loyalty member (True/False): \")\nprint(\"Apply discount:\", bool(member))\n"},"id":"w2-dbg-5","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"guidance":"Non-empty strings are True, so bool(\"False\") is True. Compare the letters the user typed.","prompt":"Program 5: why is bool(\"False\") the wrong fix?","questionId":"u14-w2-dbg-5e"},"id":"w2-dbg-5e","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"short-response","version":"0.1.0"}],"id":"week-2-conversion-debugging","metadata":{"href":null,"status":"available","summary":"Inspect five programs that fail because of missing or incorrect conversion, repair each one, and explain the cause.","title":"Five conversion debugging programs"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Messy customer rows"},"id":"w2-cln-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"A caf\u00e9 exports bookings with extra spaces, mixed case and a combined address field. Choose the predefined subroutine that cleans each part. Keep legitimate names and address formats."},"id":"w2-cln-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"instructions":"These are messy exported rows, not a program to run. Notice extra spaces, mixed case and combined address fields.","label":"Sample customer export","language":"python","questionId":"u14-w2-cln-sample","starter":"  Mary-Anne O'Neill  | Mary.Anne@Example.COM | 12 High Street,  Leeds | ls1 4ap | SKU-18\nNg\u1ecdc Tr\u1ea7n-Garc\u00eda     | ngoc@example.com      | Flat 2, 4 King's Rd, York | yo1 7hh | SKU-7\n"},"id":"w2-cln-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"code-editor","version":"0.1.0"},{"content":{"categories":[{"id":"strip","label":"strip"},{"id":"lower","label":"lower"},{"id":"upper","label":"upper"},{"id":"split","label":"split"},{"id":"replace","label":"replace"},{"id":"len","label":"len"}],"feedback":{"correct":"The subroutine should match the job. Inclusive names stay intact.","incorrect":"Trim with strip, normalise case with lower/upper, split fields, replace doubled spaces, len for length."},"formative":true,"items":[{"correctCategoryId":"strip","id":"name","label":"Trim spaces around Mary-Anne O'Neill without removing the hyphen"},{"correctCategoryId":"lower","id":"email","label":"Store Mary.Anne@Example.COM consistently"},{"correctCategoryId":"upper","id":"postcode","label":"Display ls1 4ap as LS1 4AP"},{"correctCategoryId":"split","id":"address","label":"Separate street from city on the comma"},{"correctCategoryId":"replace","id":"double","label":"Turn two spaces in \"Street,  Leeds\" into one space"},{"correctCategoryId":"len","id":"sku","label":"Check the product code length"}],"prompt":"Choose the subroutine for each cleaning job.","questionId":"u14-w2-cln-class"},"id":"w2-cln-class","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include strip(), lower(), upper() and split().","passFeedback":"The cleaning calls are present. Run the file in Python and check the name still includes the hyphen and apostrophe.","required":[{"label":"strip()","pattern":"strip\\s*\\("},{"label":"lower()","pattern":"lower\\s*\\("},{"label":"upper()","pattern":"upper\\s*\\("},{"label":"split()","pattern":"split\\s*\\("}]},"hints":["Keep hyphens and apostrophes in names.","split(\",\") separates street and city.","replace can tidy doubled spaces after you split or before."],"instructions":"Clean one customer row: strip the name, lower the email, upper the postcode, split the address. The check looks for those calls.","label":"Python editor","language":"python","questionId":"u14-w2-cln-code","starter":"raw_name = \"  Mary-Anne O'Neill  \"\nraw_email = \"Mary.Anne@Example.COM\"\nraw_address = \"12 High Street,  Leeds\"\nraw_postcode = \"ls1 4ap\"\n# Clean each field with an appropriate predefined subroutine.\n"},"id":"w2-cln-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"prompt":"Which name or address feature must not be removed during cleaning, and why?","questionId":"u14-w2-cln-ref"},"id":"w2-cln-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-2-customer-data-cleaning","metadata":{"href":null,"status":"available","summary":"Select and apply strip, upper/lower, split, replace and len to messy customer data.","title":"Customer-data cleaning"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"River Caf\u00e9 takeaway"},"id":"w2-calc-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Write a short program for a takeaway order. Collect numeric values as text, convert them, then calculate subtotal, 20% VAT and total. Print a labelled receipt with f-strings. Work in your cloned repository; the hub only checks structure."},"id":"w2-calc-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Include input(), int(), float() and an f-string print.","passFeedback":"The program collects text, converts, and uses an f-string. Run it in Python and commit it on your feature branch.","required":[{"label":"input()","pattern":"input\\s*\\("},{"label":"int()","pattern":"int\\s*\\("},{"label":"float()","pattern":"float\\s*\\("},{"label":"f-string print","pattern":"print\\s*\\(\\s*f[\"']"}]},"hints":["int() for quantity, float() for price.","subtotal = quantity * unit_price.","vat = subtotal * 0.2; total = subtotal + vat.","Use f-strings and :.2f for money."],"instructions":"Ask for quantity and unit price as text, convert, calculate subtotal, VAT and total, then print an f-string receipt. The browser does not execute this.","label":"Python editor","language":"python","questionId":"u14-w2-calc-code","starter":"# River Caf\u00e9 takeaway \u2014 Week 2\n# Collect text, convert, then calculate.\n\ncustomer = input(\"Customer name: \")\nquantity_text = input(\"Number of items: \")\nprice_text = input(\"Unit price: \")\n\n# Convert, calculate subtotal, VAT (20%) and total, then print a receipt.\n"},"id":"w2-calc-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"prompt":"Which conversion was essential for the VAT line, and what would happen without it?","questionId":"u14-w2-calc-ref"},"id":"w2-calc-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"}],"id":"week-2-business-calculation","metadata":{"href":null,"status":"available","summary":"Collect numeric business data as text, convert it, and calculate subtotal, tax and total.","title":"Independent business calculation"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Commit on a feature branch"},"id":"w2-git-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Do not commit Week 2 work only on main if your team uses feature branches. Create a short, named branch, commit the working calculation incrementally, then push. Use GitHub and Git on your machine. This hub does not run Git."},"id":"w2-git-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"Suggested branch name: **feature/week-2-conversion**\n\nIncremental commits, for example:\n\n* convert quantity and price\n* add VAT and receipt output\n* extend .gitignore\n\nUse the commands your teacher demonstrated. Do not paste secrets into commit messages."},"id":"w2-git-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"},{"content":{"correctOptionId":"a","feedback":{"correct":"The name describes the week and the work.","incorrect":"Prefer a feature name that another learner can understand later."},"formative":true,"options":[{"id":"a","label":"feature/week-2-conversion"},{"id":"b","label":"update"},{"id":"c","label":"final-final-2"}],"prompt":"Which branch name best matches this week's work?","questionId":"u14-w2-git-q1"},"id":"w2-git-q","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"prompt":"Write the branch name you will use and the first commit message for the calculation program.","questionId":"u14-w2-git-ref"},"id":"w2-git-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"text":"The hub cannot create branches or commits. Use your cloned Classroom repository.","title":"Guidance only","tone":"info"},"id":"w2-git-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-2-git-branch-guidance","metadata":{"href":null,"status":"available","summary":"Commit the working program on an appropriately named feature branch. Guidance only; this hub is not a Git client.","title":"Named feature branch"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"P1 notes this week"},"id":"w2-a1-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"P1 asks you to show understanding of the programming constructs used to build software for business. This week add two constructs: data type conversion and predefined subroutines. Completing these boxes is not P1 achieved. Your teacher assesses the submitted technical guide."},"id":"w2-a1-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"text":"For **each** construct record:\n\n* an explanation\n* its purpose\n* a worked Python example\n* why a business program needs it"},"id":"w2-a1-md","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"},{"content":{"prompt":"Draft the conversion section: explanation, purpose, a short Python example, and a business reason.","questionId":"u14-w2-a1-conv"},"id":"w2-a1-conv","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"prompt":"Draft the predefined-subroutines section: explanation, purpose, a short Python example, and a business reason.","questionId":"u14-w2-a1-sub"},"id":"w2-a1-sub","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"href":"assignments/assignment-1/","label":"Open the Assignment 1 workspace"},"id":"w2-a1-link","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reference","version":"0.1.0"},{"content":{"text":"The hub never awards Pass, Merit or Distinction. Saving these notes does not mean P1 is achieved.","title":"Not a grade","tone":"warning"},"id":"w2-a1-note","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"}],"id":"week-2-assignment-1-guide","metadata":{"href":null,"status":"available","summary":"Add P1 preparation for data type conversion and predefined subroutines. Hub completion is not P1 achieved.","title":"Assignment 1: conversion and subroutines"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"},{"blocks":[{"content":{"level":4,"text":"Directed independent study"},"id":"w2-hw-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Finish the River Caf\u00e9 calculation in your cloned repository if you did not complete it in Session 2. Convert input before arithmetic, print a receipt with f-strings, extend .gitignore if needed, and commit on your named feature branch. Then finish the Assignment 1 notes for conversion and predefined subroutines."},"id":"w2-hw-p","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"checks":{"failFeedback":"Keep int(), float() and an f-string print.","passFeedback":"The homework program still converts and formats. Commit and push on GitHub, then complete the P1 drafts.","required":[{"label":"int()","pattern":"int\\s*\\("},{"label":"float()","pattern":"float\\s*\\("},{"label":"f-string print","pattern":"print\\s*\\(\\s*f[\"']"}]},"hints":["Commit on feature/week-2-conversion or the name you chose.","Push to GitHub. The hub is not the repository."],"instructions":"Continue the calculation here if useful, but the assessed copy is the file in your GitHub repository. The check looks for conversion and an f-string only.","label":"Python editor","language":"python","questionId":"u14-w2-hw-code","starter":"# Homework \u2014 finish the takeaway calculation\ncustomer = input(\"Customer name: \")\nquantity = int(input(\"Number of items: \"))\nunit_price = float(input(\"Unit price: \"))\nsubtotal = quantity * unit_price\nvat = subtotal * 0.2\ntotal = subtotal + vat\nprint(f\"{customer}: subtotal \u00a3{subtotal:.2f}, VAT \u00a3{vat:.2f}, total \u00a3{total:.2f}\")\n"},"id":"w2-hw-ex","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"python-exercise","version":"0.1.0"},{"content":{"prompt":"Confirm what you committed (calculation, .gitignore change, P1 notes) and the branch name.","questionId":"u14-w2-hw-ref"},"id":"w2-hw-ref","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reflection","version":"0.1.0"},{"content":{"text":"More confident learners may try: try/except around a failed int() or float(); observe that int(19.99) truncates rather than rounding; and tidy commit history on the feature branch. These are not required Week 2 outcomes.","title":"Stretch (optional)","tone":"info"},"id":"w2-hw-stretch","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"text":"Week 3 introduces selection. Do not start selection work yet. Keep Assignment 1 focused on conversion and predefined subroutines from this week.","title":"What next","tone":"info"},"id":"w2-hw-next","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"callout","version":"0.1.0"},{"content":{"href":"assignments/assignment-1/","label":"Open the Assignment 1 workspace"},"id":"w2-hw-link","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"reference","version":"0.1.0"}],"id":"week-2-homework","metadata":{"href":null,"status":"available","summary":"Complete the directed independent study from the Scheme of Learning, with optional stretch for more confident learners.","title":"Homework: finish calculation and P1 notes"},"relationships":{"assets":[],"assignment":"A1","criteria":["P1"],"learningOutcomes":["LO1"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"0.1.0"}],"assets":[],"assignments":[{"id":"A1","metadata":{"criteria":[{"id":"P1","summary":"Show understanding of the programming constructs used to build software for business.","title":"Universal programming constructs"}],"dueDate":null,"evidence